/**
 * Static asset serving for the single-page app.
 *
 * Two rules matter for the product:
 *   - Hashed build assets are cached hard; `index.html` never is, so a new
 *     release is picked up on the next load.
 *   - Any unknown non-API path falls back to `index.html`, which is what makes
 *     reloading a deep link such as /admin/settings land on that same screen
 *     instead of a 404.
 */
import { createReadStream, existsSync, statSync } from 'node:fs'
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { Readable } from 'node:stream'

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.map': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json',
  '.txt': 'text/plain; charset=utf-8',
  '.xml': 'application/xml; charset=utf-8',
  '.mp4': 'video/mp4',
}

export interface StaticOptions {
  root: string
  /** Extra origins the page may talk to, e.g. a self-hosted AI endpoint. */
  connectSources?: string[]
}

export class StaticFiles {
  private readonly root: string
  private readonly indexPath: string
  private indexCache: { body: string; mtimeMs: number } | null = null

  constructor(private readonly options: StaticOptions) {
    this.root = path.resolve(options.root)
    this.indexPath = path.join(this.root, 'index.html')
  }

  get available(): boolean {
    return existsSync(this.indexPath)
  }

  /** Serves a file, or the SPA shell when the path is a client-side route. */
  async serve(request: Request, pathname: string): Promise<Response> {
    const resolved = this.resolve(pathname)
    // `/` resolves to index.html on disk, but the shell must still come back
    // with its security headers and no-store - so it always goes through
    // shell(), never the generic file path.
    if (resolved === this.indexPath) return this.shell(request)
    if (resolved) {
      const stat = statSync(resolved)
      const ext = path.extname(resolved).toLowerCase()
      const isHashed = /\/assets\/|-[0-9a-f]{8,}\./.test(resolved)
      const headers = new Headers({
        'content-type': MIME[ext] ?? 'application/octet-stream',
        'content-length': String(stat.size),
        'cache-control': isHashed ? 'public, max-age=31536000, immutable' : 'public, max-age=60',
        'x-content-type-options': 'nosniff',
      })
      if (request.method === 'HEAD') return new Response(null, { status: 200, headers })
      const stream = Readable.toWeb(createReadStream(resolved)) as ReadableStream
      return new Response(stream, { status: 200, headers })
    }
    return this.shell(request)
  }

  /** The SPA shell with the security headers the spec requires (SEC-03). */
  async shell(request: Request): Promise<Response> {
    if (!this.available) {
      return new Response(
        '<!doctype html><meta charset="utf-8"><title>yeopjari</title>' +
          '<p>웹 빌드가 없습니다. <code>npm run build -w @yeopjari/web</code>를 실행해 주세요.</p>',
        { status: 503, headers: { 'content-type': 'text/html; charset=utf-8' } },
      )
    }
    const stat = statSync(this.indexPath)
    if (!this.indexCache || this.indexCache.mtimeMs !== stat.mtimeMs) {
      this.indexCache = { body: await readFile(this.indexPath, 'utf8'), mtimeMs: stat.mtimeMs }
    }
    const headers = new Headers({
      'content-type': 'text/html; charset=utf-8',
      'cache-control': 'no-store',
      'content-security-policy': this.csp(),
      'x-content-type-options': 'nosniff',
      'referrer-policy': 'strict-origin-when-cross-origin',
      'x-frame-options': 'DENY',
      'permissions-policy': 'geolocation=(), camera=(), microphone=(), payment=()',
      'cross-origin-opener-policy': 'same-origin',
    })
    if (request.method === 'HEAD') return new Response(null, { status: 200, headers })
    return new Response(this.indexCache.body, { status: 200, headers })
  }

  private csp(): string {
    const connect = ["'self'", ...(this.options.connectSources ?? [])].join(' ')
    return [
      "default-src 'self'",
      "base-uri 'self'",
      "script-src 'self'",
      // Mantine injects a CSS-variable style block at runtime.
      "style-src 'self' 'unsafe-inline'",
      "img-src 'self' data: blob:",
      "font-src 'self' data:",
      `connect-src ${connect}`,
      "form-action 'self'",
      "frame-ancestors 'none'",
      "object-src 'none'",
      'upgrade-insecure-requests',
    ].join('; ')
  }

  /** Maps a URL path to a file inside the root, refusing traversal. */
  private resolve(pathname: string): string | null {
    let decoded: string
    try {
      decoded = decodeURIComponent(pathname)
    } catch {
      return null
    }
    if (decoded.includes('\0')) return null
    const candidate = path.resolve(this.root, `.${path.posix.normalize(decoded)}`)
    if (candidate !== this.root && !candidate.startsWith(this.root + path.sep)) return null
    if (!existsSync(candidate)) return null
    const stat = statSync(candidate)
    if (stat.isDirectory()) {
      const index = path.join(candidate, 'index.html')
      return existsSync(index) ? index : null
    }
    return stat.isFile() ? candidate : null
  }
}
#!/usr/bin/env node
/**
 * Node entry point.
 *
 * Used for local development, the end-to-end tests, and the offline container
 * image - one process that serves the API and the built SPA from the same
 * origin, so cookies and CSP behave exactly as they do on the hosted launch.
 */
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http'
import path from 'node:path'
import { Readable } from 'node:stream'
import process from 'node:process'
import { createApp, EnvError } from '@yeopjari/core'
import { StaticFiles } from './static.js'

const port = Number(process.env.PORT ?? process.env.YEOPJARI_PORT ?? 8787)
const host = process.env.YEOPJARI_HOST ?? '0.0.0.0'
const webRoot = process.env.YEOPJARI_WEB_ROOT ?? path.resolve(process.cwd(), 'apps/web/dist')

let app: ReturnType<typeof createApp>
try {
  app = createApp(process.env as Record<string, string | undefined>, { maxConnections: 10 })
} catch (err) {
  if (err instanceof EnvError) {
    console.error(`설정 오류: ${err.message}`)
    process.exit(2)
  }
  throw err
}

const aiBase = (process.env.YEOPJARI_AI_BASE_URL ?? '').trim()
const staticFiles = new StaticFiles({
  root: webRoot,
  connectSources: aiBase ? [safeOrigin(aiBase)] : [],
})

const report = await app.bootstrap()
for (const warning of report.warnings) console.warn(`주의: ${warning}`)

const server = createServer((req, res) => {
  void handle(req, res).catch((err: unknown) => {
    console.error(JSON.stringify({ level: 'error', message: '요청 처리 실패', detail: String(err) }))
    if (!res.headersSent) res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' })
    res.end(JSON.stringify({ error: { code: 'internal', message: '처리 중 문제가 발생했습니다.' } }))
  })
})

server.keepAliveTimeout = 65_000
server.headersTimeout = 70_000
// No request timeout: AI streaming responses are intentionally long-lived.
server.requestTimeout = 0

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const request = toRequest(req)
  const url = new URL(request.url)

  const isApi =
    url.pathname.startsWith('/api/') ||
    url.pathname.startsWith('/.well-known/') ||
    url.pathname === '/mcp' ||
    // The OAuth browser entry point is a route, not a page: it hands the
    // request to the consent screen. Served by the SPA instead, an MCP client
    // or a sister service (your.yeopjari.bid) landed on the front page.
    url.pathname === '/oauth/authorize' ||
    url.pathname.startsWith('/mcp/') ||
    // Server-rendered public pages (routes/public-pages.ts), not the SPA.
    url.pathname.startsWith('/c/') ||
    url.pathname === '/sitemap.xml' ||
    url.pathname.startsWith('/sitemaps/') ||
    // Workplaces from the pension register (routes/workplaces.ts, 0051).
    url.pathname === '/w' ||
    url.pathname.startsWith('/w/') ||
    url.pathname === '/ads.txt' ||
    url.pathname === '/ad-policy' ||
    url.pathname === '/rank' ||
    url.pathname.startsWith('/rank/') ||
    url.pathname === '/compare' ||
    url.pathname.startsWith('/compare/') ||
    url.pathname.startsWith('/tools/') ||
    url.pathname === '/briefing' ||
    url.pathname.startsWith('/briefing/') ||
    /^\/(google|naver)[0-9a-z]+\.html$/.test(url.pathname) ||
    /^\/[0-9a-f]{32}\.txt$/.test(url.pathname)

  const response = isApi
    ? await app.fetch(request)
    : request.method === 'GET' || request.method === 'HEAD'
      ? await staticFiles.serve(request, url.pathname)
      : new Response(JSON.stringify({ error: { code: 'not_found', message: '요청한 경로가 없습니다.' } }), {
          status: 404,
          headers: { 'content-type': 'application/json; charset=utf-8' },
        })

  // A route may answer without reading the body: an early 401, a 413, or an
  // idempotent replay that already knows the result. Those bytes are still in
  // the socket, and leaving them there poisons the connection - the next
  // request on it is reset. Draining has to go through the same web stream the
  // request was built from, because converting the Node stream handed it over.
  const drained = await drainBody(request)
  if (!drained) {
    // Too large to discard: let Node close the connection rather than hand a
    // half-read socket to the next request.
    response.headers.set('connection', 'close')
  }
  await writeResponse(res, response)
}

/** Largest unread body we will discard to keep a connection reusable. */
const MAX_DRAIN_BYTES = 8 * 1024 * 1024

async function drainBody(request: Request): Promise<boolean> {
  const body = request.body
  if (!body || request.bodyUsed) return true
  const reader = body.getReader()
  let seen = 0
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) return true
      seen += value?.byteLength ?? 0
      if (seen > MAX_DRAIN_BYTES) {
        await reader.cancel().catch(() => undefined)
        return false
      }
    }
  } catch {
    return false
  }
}

/**
 * Whether a reverse proxy in front of this server sets the client address.
 *
 * Only when the operator says so (YEOPJARI_TRUST_PROXY=true). Otherwise these
 * headers come from the client itself, and believing them let anyone pick
 * the address the sign-in and sign-up limits count against - a fresh one per
 * attempt. A proxy that is trusted must overwrite X-Real-IP; the first entry
 * of X-Forwarded-For is whatever the client put there.
 */
const behindProxy = ['1', 'true', 'yes', 'on'].includes(
  (process.env.YEOPJARI_TRUST_PROXY ?? '').trim().toLowerCase(),
)
const CLIENT_ADDRESS_HEADERS = new Set(['cf-connecting-ip', 'x-real-ip', 'x-forwarded-for', 'true-client-ip'])

function toRequest(req: IncomingMessage): Request {
  const forwardedProto = (req.headers['x-forwarded-proto'] as string | undefined)?.split(',')[0]?.trim()
  const proto = forwardedProto || 'http'
  const host = (req.headers.host ?? `localhost:${port}`).toString()
  const url = `${proto}://${host}${req.url ?? '/'}`

  const headers = new Headers()
  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) continue
    if (!behindProxy && CLIENT_ADDRESS_HEADERS.has(key.toLowerCase())) continue
    if (Array.isArray(value)) for (const entry of value) headers.append(key, entry)
    else headers.set(key, value)
  }
  // Without a proxy in front, the only address worth believing is the
  // socket's. Anything the client sent saying otherwise was dropped above.
  if (!behindProxy && req.socket.remoteAddress) headers.set('x-real-ip', req.socket.remoteAddress)

  const method = (req.method ?? 'GET').toUpperCase()
  const hasBody = method !== 'GET' && method !== 'HEAD'
  return new Request(url, {
    method,
    headers,
    body: hasBody ? (Readable.toWeb(req) as ReadableStream) : null,
    // @ts-expect-error Node requires duplex for streaming request bodies
    duplex: hasBody ? 'half' : undefined,
  })
}

async function writeResponse(res: ServerResponse, response: Response): Promise<void> {
  const headers: Record<string, string | string[]> = {}
  for (const [key, value] of response.headers.entries()) {
    if (key.toLowerCase() === 'set-cookie') continue
    headers[key] = value
  }
  const cookies = response.headers.getSetCookie?.() ?? []
  if (cookies.length > 0) headers['set-cookie'] = cookies

  res.writeHead(response.status, headers)
  if (!response.body) {
    res.end()
    return
  }
  const reader = response.body.getReader()
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      if (value) {
        if (!res.write(value)) {
          await new Promise<void>((resolve) => res.once('drain', resolve))
        }
      }
    }
  } finally {
    res.end()
  }
}

function safeOrigin(value: string): string {
  try {
    return new URL(value).origin
  } catch {
    return ''
  }
}

server.listen(port, host, () => {
  const info = app.env.build
  console.log(
    `yeopjari v${info.version} (${info.commit}) 시작 - http://${host === '0.0.0.0' ? 'localhost' : host}:${port}` +
      `${staticFiles.available ? '' : ' (웹 빌드 없음: API만 제공)'}`,
  )
})

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    server.close(() => {
      void app.close().then(() => process.exit(0))
    })
    setTimeout(() => process.exit(0), 8000).unref()
  })
}
